%[text] %[text:anchor:H_2F7456E7] ## Practice Randomized Substitution Integrals
%[text] ![](text:image:2a7e) **Pro-tip**. MATLAB syntax is 7`*t^(2/3)` for $7t^{2/3}${"altText":"7t^(2\/3)"}. The variable you use in the solution matters, as does appropriate use of parentheses and multiplication operators.
% Clear variables that may be reused in other parts of this module
clear ErrorCount TotSubProbs TotAttempts adjustcount LastFive MyFun VarChoice
syms t r x z C              % Declare symbolic variables
VarOpts = [t r x z];        % Define the list of variables to use in the problems
ErrorCount = 0;             % Initialize a count of errors
TotSubProbs = 0;            % Initialize a count of total problems attempted
TotAttempts = 0;            % Initialize a count of total solutions offered
AdjustCount = 0;            % Preserve the counts if the user resubmits a solution
LastFive = zeros(1,5);      % Initialize a matrix to record the last five solution results
  %[control:button:3b73]{"position":[1,2]}
disp("Values initialized for Substitution Practice.") %[output:532d8ea2]
%%
% Check if the previous section has run
% If not, provide warning. If so, generate a problem.
if ~exist("TotSubProbs","var") %[output:group:61c2006e]
    warning("You must initialize values before you can generate a problem.")
else
    [MyFun,VarChoice] = GenProbType(VarOpts,1);  % genProbType is defined in Helper Functions %[output:47db11ab] %[output:9b7433a9]
    % genProbType sets up a variable and generates a randomized function
    TotSubProbs = TotSubProbs+1;     % Increase the count of total problems attempted
end %[output:group:61c2006e]
                                   % Run this section %[control:button:66ca]{"position":[1,2]}
%%
MyAnswer = 1/4*((1/cos(4*t))+(1/cos(4*t))^2/2+1/16*(1/cos(4*t))^3)+C;     % User-defined solution, default value r %[control:editfield:4cdc]{"position":[12,69]}
TotAttempts = TotAttempts + 1;       % Updates count of total attempts at solution
[LastFive,ErrorCount,TotAttempts,AdjustCount] = ResubmissionCheck(TotAttempts,TotSubProbs, ... %[output:group:9315b549] %[output:9dc33591] %[output:06566619] %[output:6be5ee37] %[output:3da3f2e7] %[output:4aa56125]
    AdjustCount,MyFun,VarChoice,MyAnswer,ErrorCount,LastFive); %[output:group:9315b549] %[output:9dc33591] %[output:06566619] %[output:6be5ee37] %[output:3da3f2e7] %[output:4aa56125]
% ResubmissionCheck is defined in Local Helper Functions
% ResubmissionCheck records the attempt and provides appropriate feedback
                          % Run this section %[control:button:4bf3]{"position":[1,2]}
%%
%[text] Once you have completed sufficient practice, track the overall results of your practice here:
  %[control:button:1227]{"position":[1,2]}
AnalyzeResults(TotSubProbs,ErrorCount,TotAttempts,AdjustCount,LastFive) %[output:3314351f]
